class Graph:
    def __init__(self, directed=True):
        self.directed = directed
        self.graph = {}

    def add_node(self, node, neighbors=None):
        if not self.graph:
            self.graph = {node: neighbors if neighbors is not None else [])
        else:
            if node not in self.graph:
                self.graph[node] = []
            if neighbors is not None:
                for neighbor in neighbors:
                    if node not in self.graph[neighbor]:
                        self.graph[node].append(neighbor)
                        if not self.directed:
                            self.graph[neighbor].append(node)

    def find_path(self, start, goal):
        if start not in self.graph or goal not in self.graph:
            return None

        visited = set()
        path_stack = [[start]]

        while path_stack:
            path = path_stack.pop(0)
            node = path[-1]

            if node == goal:
                # Ensure the path is only one node long if it's the goal itself
                if len(path) == 1 or path[-2] != goal:
                    return path
            elif node not in visited:
                visited.add(node)
                for neighbor in self.graph[node]:
                    if neighbor not in visited:
                        path_stack.append(path + [neighbor])

        return None

def find_path(graph, start, goal):
    return Graph().add_node(*graph).find_path(start, goal)

